7	import { type FunctionCall } from '@google/genai';
8	import {
9	  PolicyDecision,
10	  type PolicyEngineConfig,
11	  type PolicyRule,
12	  type SafetyCheckerRule,
13	  type HookCheckerRule,
14	  ApprovalMode,
15	  type CheckResult,
16	  ALWAYS_ALLOW_PRIORITY_FRACTION,
17	} from './types.js';
18	import { stableStringify } from './stable-stringify.js';
19	import { debugLogger } from '../utils/debugLogger.js';
20	import type { CheckerRunner } from '../safety/checker-runner.js';
21	import { SafetyCheckDecision } from '../safety/protocol.js';
22	import {
23	  SHELL_TOOL_NAMES,
24	  initializeShellParsers,
25	  splitCommands,
26	  hasRedirection,
27	} from '../utils/shell-utils.js';
28	import { getToolAliases } from '../tools/tool-names.js';
29	import {
30	  MCP_TOOL_PREFIX,
31	  isMcpToolAnnotation,
32	  parseMcpToolName,
33	} from '../tools/mcp-tool.js';
34	
35	function isWildcardPattern(name: string): boolean {
36	  return name === '*' || name.includes('*');
37	}
38	
39	/**
40	 * Checks if a tool call matches a wildcard pattern.
41	 * Supports global (*) and the explicit MCP (*mcp_serverName_**) format.
42	 */
43	function matchesWildcard(
44	  pattern: string,
45	  toolName: string,
46	  serverName: string | undefined,
47	): boolean {
48	  if (pattern === '*') {
49	    return true;
50	  }
51	
52	  if (pattern === `${MCP_TOOL_PREFIX}*`) {
53	    return serverName !== undefined;
54	  }
55	
56	  if (pattern.startsWith(MCP_TOOL_PREFIX) && pattern.endsWith('_*')) {
57	    const expectedServerName = pattern.slice(MCP_TOOL_PREFIX.length, -2);
58	    // 1. Must be an MCP tool call (has serverName)
59	    // 2. Server name must match
60	    // 3. Tool name must be properly qualified by that server
61	    if (serverName === undefined || serverName !== expectedServerName) {
62	      return false;
63	    }
64	    return toolName.startsWith(`${MCP_TOOL_PREFIX}${expectedServerName}_`);
65	  }
66	
67	  // Not a recognized wildcard pattern, fallback to exact match just in case
68	  return toolName === pattern;
69	}
70	
71	function ruleMatches(
72	  rule: PolicyRule | SafetyCheckerRule,
73	  toolCall: FunctionCall,
74	  stringifiedArgs: string | undefined,
75	  serverName: string | undefined,
76	  currentApprovalMode: ApprovalMode,
77	  nonInteractive: boolean,
78	  toolAnnotations?: Record<string, unknown>,
79	  subagent?: string,
80	): boolean {
81	  // Check if rule applies to current approval mode
82	  if (rule.modes && rule.modes.length > 0) {
83	    if (!rule.modes.includes(currentApprovalMode)) {
84	      return false;
85	    }
86	  }
87	
88	  // Check subagent if specified (only for PolicyRule, SafetyCheckerRule doesn't have it)
89	  if ('subagent' in rule && rule.subagent) {
90	    if (rule.subagent !== subagent) {
91	      return false;
92	    }
93	  }
94	
95	  // Strictly enforce mcpName identity if the rule dictates it
96	  if (rule.mcpName) {
97	    if (rule.mcpName === '*') {
98	      // Rule requires it to be ANY MCP tool
99	      if (serverName === undefined) return false;
100	    } else {
101	      // Rule requires it to be a specific MCP server
102	      if (serverName !== rule.mcpName) return false;
103	    }
104	  }
105	
106	  // Check tool name if specified
107	  if (rule.toolName) {
108	    // Support wildcard patterns: "mcp_serverName_*" matches "mcp_serverName_anyTool"
109	    if (rule.toolName === '*') {
110	      // Match all tools
111	    } else if (isWildcardPattern(rule.toolName)) {
112	      if (
113	        !toolCall.name ||
114	        !matchesWildcard(rule.toolName, toolCall.name, serverName)
115	      ) {
116	        return false;
117	      }
118	    } else if (toolCall.name !== rule.toolName) {
119	      return false;
120	    }
121	  }
122	
123	  // Check annotations if specified
124	  if (rule.toolAnnotations) {
125	    if (!toolAnnotations) {
126	      return false;
127	    }
128	    for (const [key, value] of Object.entries(rule.toolAnnotations)) {
129	      if (toolAnnotations[key] !== value) {
130	        return false;
131	      }
132	    }
133	  }
134	
135	  // Check args pattern if specified
136	  if (rule.argsPattern) {
137	    // If rule has an args pattern but tool has no args, no match
138	    if (!toolCall.args) {
139	      return false;
140	    }
141	    // Use stable JSON stringification with sorted keys to ensure consistent matching
142	    if (
143	      stringifiedArgs === undefined ||
144	      !rule.argsPattern.test(stringifiedArgs)
145	    ) {
146	      return false;
147	    }
148	  }
149	
150	  // Check interactive if specified
151	  if ('interactive' in rule && rule.interactive !== undefined) {
152	    if (rule.interactive && nonInteractive) {
153	      return false;
154	    }
155	    if (!rule.interactive && !nonInteractive) {
156	      return false;
157	    }
158	  }
159	
160	  return true;
161	}
